const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

function makeTransport(script = []) {
  const calls = [];
  return {
    calls,
    async acknowledge(receipt) {
      calls.push(receipt);
      const step = script.shift();
      if (step) throw step;
    },
  };
}

async function main() {
  // Repeated equal amount: one debit, original receipt returned.
  {
    const ledger = new Ledger();
    const svc = new PaymentService(ledger, makeTransport());
    const a = await svc.pay('t1', 'k1', 500);
    const b = await svc.pay('t1', 'k1', 500);
    assert.equal(ledger.entries.length, 1);
    assert.equal(a, b);
    assert.deepEqual(b, { id: 1, tenant: 't1', key: 'k1', cents: 500 });
  }

  // Concurrent equal calls: one debit, every caller gets the same receipt.
  {
    const ledger = new Ledger();
    const svc = new PaymentService(ledger, makeTransport());
    const results = await Promise.all(Array.from({ length: 10 }, () => svc.pay('t1', 'k1', 500)));
    assert.equal(ledger.entries.length, 1);
    for (const r of results) assert.equal(r, results[0]);
  }

  // Same key with another amount: 'key conflict', no extra debit.
  {
    const ledger = new Ledger();
    const svc = new PaymentService(ledger, makeTransport());
    await svc.pay('t1', 'k1', 500);
    await assert.rejects(svc.pay('t1', 'k1', 501), { message: 'key conflict' });
    await assert.rejects(svc.pay('t1', 'k1', 501), { message: 'key conflict' });
    assert.equal(ledger.entries.length, 1);
  }

  // Scoping: same key under different tenants is a different payment.
  {
    const ledger = new Ledger();
    const svc = new PaymentService(ledger, makeTransport());
    const a = await svc.pay('t1', 'k1', 500);
    const b = await svc.pay('t2', 'k1', 900);
    assert.equal(ledger.entries.length, 2);
    assert.notEqual(a.id, b.id);
    assert.deepEqual(b, { id: 2, tenant: 't2', key: 'k1', cents: 900 });
  }

  // Ack throws Transient after the debit committed: retry, same receipt, one debit.
  {
    const ledger = new Ledger();
    const transport = makeTransport([new Transient('late')]);
    const svc = new PaymentService(ledger, transport);
    const r = await svc.pay('t1', 'k1', 500);
    assert.equal(ledger.entries.length, 1);
    assert.equal(transport.calls.length, 2);
    assert.equal(transport.calls[0], transport.calls[1]);
    assert.equal(transport.calls[1], r);
  }

  // Retries exhausted: the final Transient is thrown, with the last attempt's error.
  {
    const ledger = new Ledger();
    let n = 0;
    const transport = { async acknowledge() { throw new Transient(`fail${++n}`); } };
    const svc = new PaymentService(ledger, transport);
    await assert.rejects(svc.pay('t1', 'k1', 500, 3), (e) => e instanceof Transient && e.message === 'fail3');
    assert.equal(n, 3);
    assert.equal(ledger.entries.length, 1);
  }

  // attempts = 1 means a single try.
  {
    const ledger = new Ledger();
    const transport = makeTransport([new Transient('x')]);
    const svc = new PaymentService(ledger, transport);
    await assert.rejects(svc.pay('t1', 'k1', 500, 1), Transient);
    assert.equal(transport.calls.length, 1);
  }

  // Non-Transient errors from ack are not retried and propagate unchanged.
  {
    const ledger = new Ledger();
    const boom = new Error('boom');
    const transport = makeTransport([boom]);
    const svc = new PaymentService(ledger, transport);
    await assert.rejects(svc.pay('t1', 'k1', 500), (e) => e === boom);
    assert.equal(transport.calls.length, 1);
  }

  // Non-Transient errors from the ledger are not retried.
  {
    const ledger = new Ledger();
    let applies = 0;
    const err = new Error('ledger down');
    ledger.apply = async () => { applies++; throw err; };
    const svc = new PaymentService(ledger, makeTransport());
    await assert.rejects(svc.pay('t1', 'k1', 500), (e) => e === err);
    assert.equal(applies, 1);
  }

  // Transient from the ledger before any debit is retried.
  {
    const ledger = new Ledger();
    const real = ledger.apply.bind(ledger);
    let applies = 0;
    ledger.apply = async (...args) => { if (++applies === 1) throw new Transient('busy'); return real(...args); };
    const svc = new PaymentService(ledger, makeTransport());
    await svc.pay('t1', 'k1', 500);
    assert.equal(applies, 2);
    assert.equal(ledger.entries.length, 1);
  }

  // Invalid input throws before any ledger or transport action.
  {
    const bad = [
      ['', 'k', 1], ['t', '', 1], [undefined, 'k', 1], ['t', null, 1],
      ['t', 'k', 0], ['t', 'k', -1], ['t', 'k', 1.5], ['t', 'k', '5'], ['t', 'k', NaN],
      ['t', 'k', 1, 0], ['t', 'k', 1, 6], ['t', 'k', 1, 1.5], ['t', 'k', 1, '3'], ['t', 'k', 1, NaN],
    ];
    for (const args of bad) {
      const ledger = new Ledger();
      let touched = 0;
      ledger.apply = async () => { touched++; throw new Error('should not run'); };
      const transport = { async acknowledge() { touched++; } };
      const svc = new PaymentService(ledger, transport);
      await assert.rejects(svc.pay(...args), { message: 'invalid payment' }, JSON.stringify(args));
      assert.equal(touched, 0, JSON.stringify(args));
    }
  }

  // Boundary values that are valid.
  {
    const ledger = new Ledger();
    const transport = makeTransport([new Transient('a'), new Transient('b'), new Transient('c'), new Transient('d')]);
    const svc = new PaymentService(ledger, transport);
    await assert.rejects(svc.pay('t', 'k', 1, 5), Transient);
    assert.equal(transport.calls.length, 5);
  }

  console.log('idempotency checks passed');
}

module.exports = main();
EOF
